  'cs.rubrics_help': 'ඔබේම ඇගයීම් පරිමාණ. ඔබ පුහුණු කරන ක්‍රීඩා සඳහා සම්මත පරිමාණ (FIFA, ICC, ඔලිම්පික් …) ඔබ වෙනුවෙන් එක් කෙරේ — ඒවා වෙනස් කරන්න, එක් කරන්න හෝ සංරක්ෂණය කරන්න. එක් රූබ්‍රික් එකකට ක්‍රීඩා කිහිපයක් ආවරණය කළ හැකි අතර, ක්‍රීඩාවකට රූබ්‍රික් කිහිපයක් තිබිය හැක. සෑම ලකුණක්ම ලබාදුන් අනුවාදය සමඟ පවතී, විවිධ පරිමාණවල ලකුණු කිසිවිටෙක මිශ්‍ර නොකරන අතර නිල සංඛ්‍යාලේඛන බවට හරවන්නේ නැත.',
