  'fedx.bgc.consentBody': 'කැමැත්ත ඇති විට පමණක් සපයන්නාගෙන් පරීක්ෂාව ඉල්ලයි. ප්‍රතිඵලය (පැහැදිලි, පැහැදිලි නැත හෝ පොරොත්තුවෙන්) පමණක් තබා ගනී; සපයන්නාගේ වාර්තාව කිසිවිටෙක නැත.',
