  'setup.step.season.w': 'වාරය ඔබේ වැඩසටහන්, කණ්ඩායම් සහ පැමිණීමට දිනයන් සපයයි.',
  'setup.step.people.t': 'ඔබේ පුද්ගලයන් ගෙන එන්න',
  'setup.step.people.w': 'TeamSnap, SportsEngine හෝ ස්ප්‍රෙඩ්ෂීට් එකකින් ඔබේ ලැයිස්තුව ආනයනය කරන්න. සුරැකීමට පෙර සියල්ල දකී.',
  'setup.step.first_transaction.t': 'ඔබේ පළමු ඉසව්ව හෝ තරගය පවත්වන්න',
  'setup.step.first_transaction.w': 'ඔබේ සාමාජිකයන්ට දැකිය හැකි සහ ප්‍රතිචාර දැක්විය හැකි දෙයක් සාදන්න.',
  'setup.step.first_transaction_academy.t': 'ඔබේ පළමු ගාස්තුව අය කරන්න',
  'setup.step.first_transaction_academy.w': 'පළමු ගාස්තුව හෝ ඉන්වොයිසිය ඔබේ මුදල් ගලනය මුල සිට අග දක්වා ක්‍රියා කරන බව ඔප්පු කරයි.',
  'setup.step.venue.t': 'ඔබේ ස්ථානය එක් කරන්න',
  'setup.step.venue.w': 'නම, ලිපිනය සහ එහි පවත්වන ක්‍රීඩා.',
  'setup.step.courts.t': 'ඔබේ පිටි, ක්‍රීඩාංගණ හෝ කාමර එක් කරන්න',
  'setup.step.courts.w': 'එක් එකකට තමන්ගේම ධාරිතාව සහ ස්ලොට් කාලය ඇත.',
  'setup.step.hours.t': 'ඔබේ විවෘත වේලාවන් සකසන්න',
  'setup.step.hours.w': 'ඔබ විවෘතව ඇති විට පමණක් පුද්ගලයන්ට වෙන්කළ හැක.',
  'setup.step.rates.t': 'ඔබේ පැය ගාස්තු සකසන්න',
  'setup.step.rates.w': 'මිලට බදු ඇතුළත්. උච්ච සහ අනුච්ච නීති පසුව එක් කළ හැක.',
  'setup.step.first_transaction_venue.t': 'ඔබේ පළමු වෙන්කිරීම ලබාගන්න',
  'setup.step.first_transaction_venue.w': 'ඔබම පරීක්ෂණ වෙන්කිරීමක් කරන්න, නැතහොත් ඔබේ ස්ථාන පිටුව බෙදාගන්න.',
  'setup.step.event.t': 'ඔබේ ඉසව්ව සාදන්න',
  'setup.step.event.w': 'ක්‍රීඩා, දින, ස්ථානය සහ ආකෘතිය.',
  'setup.step.open.t': 'ඇතුළත් වීම් සඳහා විවෘත කරන්න',
  'setup.step.open.w': 'ඉසව්ව විවෘත වූ පසු පමණක් කණ්ඩායම්වලට ඇතුළත් විය හැක.',
  'setup.step.first_transaction_organiser.t': 'ඔබේ පළමු තරග සැලසුම් කරන්න',
  'setup.step.first_transaction_organiser.w': 'කාලසටහන ඔබ වෙනුවෙන් විනිසුරු සහ කණ්ඩායම් ගැටුම් පරීක්ෂා කරයි.',
  'setup.step.profile.t': 'ඔබේ පුහුණුකරු පැතිකඩ සකසන්න',
  'setup.step.profile.w': 'ඔබේ ශීර්ෂය, විශේෂඥතා සහ වේලාවන්, පුද්ගලයන්ට ඔබව සොයා වෙන්කළ හැකි වන පරිදි.',
  'setup.step.team.t': 'ඔබේ කණ්ඩායම සාදන්න',
  'setup.step.team.w': 'ඔබේ ලැයිස්තුව, ලබාගත හැකි බව සහ කාලසටහන මෙහි ඇත.',
  'setup.step.first_transaction_coach.t': 'ඔබේ ක්‍රීඩකයන්ට ආරාධනා කරන්න',
  'setup.step.first_transaction_coach.w': 'ඔබ දන්නා අයට ආරාධනා කරන්න, නැතහොත් සංවිධාන වැඩ අවකාශයකින් සම්පූර්ණ ලැයිස්තුවක් ගෙන එන්න.',
  "paycountry.title": "රට අනුව ගෙවීම් ක්‍රම",
  "paycountry.intro": "ගෙවීම් ක්‍රමයක් ක්‍රියාත්මක කිරීමට හෝ නතර කිරීමට හැක්කේ වේදිකා පරිපාලකයාට පමණි. ස්විචයක් නැති රටක සියලු ක්‍රම අක්‍රියයි. සෑම වෙන්කිරීමක්, පන්තියක්, ටිකට්පතක්, ලියාපදිංචියක් සහ සාප්පු චෙක්අවුට් එකක්ම ඒ රටට සක්‍රිය ක්‍රම පමණක් පෙන්වයි.",
