  'coachSub.autoNote': 'මෙම පළමු ගෙවීමෙන් පසු ඔබට ස්වයංක්‍රීය ගෙවීම සක්‍රිය කළ හැක, එවිට ඉදිරි මාස ඔබ වෙනුවෙන් අය කෙරේ. මෙය සැමවිටම විකල්පයකි.',
