  'aco.src.body': 'කාර්ය මණ්ඩල පිරිවැය අනුමත වැටුප් ලේඛනයෙන් ද ස්ථාන පිරිවැය තහවුරු කළ ස්ථාන වෙන්කිරීම්වලින් ද ලැබේ. වැඩසටහනකට මේවා නැති විට පමණක් අතින් ඇතුළත් කළ පිරිවැය භාවිත වේ.',
  'aco.src.unpriced': 'අනුමත කාල පත්‍ර {n} කට වැටුප් නියමයක් නැත, එබැවින් ඒවායේ පිරිවැය ගණනය නොකෙරේ.',
  'aco.src.unbooked': 'සැසි {n} කට ස්ථාන වෙන්කිරීමක් නැත, එබැවින් ඒවායේ ස්ථාන පිරිවැය ගණනය නොකෙරේ.',
  'aco.src.superseded': 'අතින් ඇතුළත් කළ ඇතුළත් කිරීම් {n} ක් පසෙකින් තබන ලදී, මන්ද වැටුප් ලේඛනය හෝ වෙන්කිරීම ඒවා දැනටමත් ආවරණය කරයි.',
  'aco.costs.intro': 'මේවා P&L සඳහා කළමනාකරණ ගිණුම්කරණ පේළි ය (ක්‍රීඩාංගන කුලිය, උපකරණ, උඩිස් පිරිවැයෙන් කොටසක්). මේවා ගෙවීම් හෝ ඉන්වොයිස් නොවේ, මුදල් චලනය නොකරයි. කාර්ය මණ්ඩල සහ ස්ථාන පිරිවැය අනුමත වැටුප් ලේඛනයෙන් සහ තහවුරු කළ වෙන්කිරීම්වලින් කියවේ; ඒවා නැති විට පමණක් මෙහි ඇතුළත් කරන්න. ඇතුළත් කිරීම් කිසිවිටක සංස්කරණය නොවේ: අවලංගු කර නැවත එක් කරන්න.',
  'aco.fund.unattributed': 'වැඩසටහනකට සම්බන්ධ නොවූ පිරිවැය',
