  'aco.branch.intro': 'වැඩසටහන් ස්ථානය අනුව කාණ්ඩ කරන්න. ශාඛාවක් එය භාවිත කරන ස්ථාන වෙත පමණක් යොමු වේ, ස්ථාන දත්ත තබා නොගනී; වැඩසටහනක් උපරිම වශයෙන් එක් ශාඛාවකට අයත් වේ. සංරක්ෂණය කළත් සියලු ඉතිහාසය රැඳේ.',
