  'guide.title': 'ඔබේ ඇකඩමිය පියවරෙන් පියවර පවත්වාගෙන යන්න',
  'guide.sub': 'නව ඇකඩමියක සිට පළමු වාර්තා දක්වා පියවර {n}ක්, තිර රූ සමඟ.',
  'guide.hide': 'මඟපෙන්වීම සඟවන්න',
  'guide.start': 'මඟපෙන්වීම ආරම්භ කරන්න',
  'guide.pdf': 'PDF බාගන්න',
