  'guide.shot_a11y': '{title} සඳහා යෙදුමේ තිර රූව',
  'guide.no_shot': 'මෙම පියවර සඳහා තිර රූවක් තවම නැත.',
  'guide.create.title': 'ඔබේ ඇකඩමිය සාදන්න',
  'guide.venues.title': 'ස්ථාන සකසන්න',
  'guide.staff.title': 'කාර්ය මණ්ඩලය එක් කරන්න',
  'guide.suppliers.title': 'සැපයුම්කරුවන් එක් කරන්න',
  'guide.programmes.title': 'වැඩසටහන් සාදන්න',
  'guide.coaches.title': 'පුහුණුකරුවන් බඳවා ගන්න',
  'guide.students.title': 'සිසුන්ට ආරාධනා කරන්න',
  'guide.classes.title': 'පන්ති ලුහුබඳින්න',
  'guide.tax.title': 'බදු සකසන්න',
  'guide.revenue.title': 'ආදායම බෙදාගන්න',
  'guide.reports.title': 'වාර්තා කියවන්න',
  'guide.create.why': 'අනෙක් සියල්ල සංවිධානයට සම්බන්ධ වන බැවින් මෙතැනින් ආරම්භ කරන්න. ඔබ එහි හිමිකරු වේ.',
  'guide.venues.why': 'සැසි, උසාවි සහ ගාස්තු ස්ථානයකට බැඳී ඇත, එබැවින් වැඩසටහන් සැලසුම් කිරීමට පෙර ඔබේ පුහුණු ස්ථාන එක් කරන්න.',
  'guide.staff.why': 'පුහුණුකරුවන්ට, ඉදිරිපස කවුන්ටරයට සහ මුදල් අංශයට වෙන වෙනම ප්‍රවේශය දෙන්න. සෑම කෙනෙක්ම දකින්නේ තම භූමිකාවට අවශ්‍ය දේ පමණි.',
  'guide.suppliers.why': 'නඩත්තු කොන්ත්‍රාත්කරුවන් සහ කට්ටල සැපයුම්කරුවන් එක් තැනක තබා, ඔවුන් සේවය කරන ස්ථානවලට සම්බන්ධ කර, ඉල්ලීම් අවසන් වන තුරු ලුහුබඳින්න.',
  'guide.programmes.why': 'පවුල් මිලදී ගන්නේ වැඩසටහනයි: කණ්ඩායමක්, වාර පාඨමාලාවක් හෝ කඳවුරක්, මිල සහ ඉඩ සමඟ.',
  'guide.coaches.why': 'පුහුණුකරුවන් සේවකයින් ලෙස, කොන්ත්‍රාත්කරුවන් ලෙස හෝ ආදායම්-හවුල්කරුවන් ලෙස ගෙන ඒම සහ කොන්දේසි ලිඛිතව එකඟ වන්න.',
  'guide.students.why': 'විමසුමේ සිට ලියාපදිංචිය දක්වා පුද්ගලයින් ගෙන යන්න. ළමයින් සඳහා දෙමාපියන් හෝ භාරකරුවන් කැමැත්ත දෙයි.',
  'guide.classes.why': 'අද සහ සතිය එක බැල්මකින් බලන්න, පැමිණීම සටහන් කරන්න, ප්‍රතිපූරණ සහ අවලංගු පන්ති පෙනෙන්නට තබන්න.',
  'guide.tax.why': 'එකතු කළ සහ ගෙවූ බදු, ඔබේ බදු නීති සහ ඉන්වොයිස්වල බදු විස්තර සමඟ දැනගන්න.',
  'guide.revenue.why': 'පුහුණුකරුවන් සමඟ මුදල් බෙදන ආකාරය සහ හවුල් වියදම් වැඩසටහන් අතර බෙදන ආකාරය එකඟ වන්න.',
  'guide.reports.why': 'විධායක මුල් පිටුවේ ප්‍රතිඵල, රඳවා ගැනීම, මූල්‍ය සෞඛ්‍යය සහ හවුල්කරුවන් බලන්න, අවශ්‍ය දේ අපනයනය කරන්න.',
  'dp.tab': 'සංවර්ධන සැලසුම්',
  'dp.title': 'ක්‍රීඩක සංවර්ධන සැලසුම්',
  'dp.subtitle': 'තාක්ෂණික, උපායමාර්ගික, ශාරීරික, මානසික, අධ්‍යාපනික සහ පුද්ගලික ක්ෂේත්‍ර හරහා එක් ක්‍රීඩකයෙකුට එක් වාරික සැලසුමක්. සාක්ෂි කියවන්නේ එහි ම වාර්තාවෙනි; කිසිවක් පිටපත් කිරීමක් හෝ ලකුණක් ලෙස ඒකාබද්ධ කිරීමක් සිදු නොවේ.',
  'dp.family_subtitle': 'ඔබේ ඇකඩමිය ඔබ සමඟ තබා ගන්නා වාරික සැලසුම: කුමක් මත වැඩ කරන්නේද, කාර්යයන්, සහ ඔබට කියවා ප්‍රතිචාර දැක්විය හැකි සමාලෝචන.',
  'dp.new_plan': 'නව සැලසුම',
  'dp.create': 'සැලසුම සාදන්න',
  'dp.created': 'සැලසුම සෑදිණි. අරමුණු එක් කරන්න, කණ්ඩායමට නම දෙන්න, ඉන්පසු සක්‍රිය කරන්න.',
  'dp.new_notice': 'සැලසුමක් එක් වාරයක් සඳහා එක් ක්‍රීඩකයෙකු වටා සිටින අය සම්බන්ධීකරණය කරයි. එය පුහුණු, පැමිණීම, පාසල් සහ මාවත් වාර්තා වලට සම්බන්ධ වේ; ඒවා කිසි විටෙක පිටපත් නොකරයි.',
  'dp.search': 'ක්‍රීඩකයා හෝ වාරය සොයන්න',
  'dp.all': 'සියල්ල',
  'dp.all_plans': 'සියලු සැලසුම්',
  'dp.none': 'තවම සංවර්ධන සැලසුම් නැත',
  'dp.none_sub': 'ලියාපදිංචි ක්‍රීඩකයෙකු සඳහා සැලසුමක් විවෘත කරන්න: වාරය, වගකිව යුතු ප්‍රධානියා සහ එක් එක් ක්ෂේත්‍රයේ අරමුණු තෝරන්න.',
