  'wb.f_sub_adult': 'ඔබ බෙදා ගැනීමට තෝරාගත් දේ, ඔබේ උපදේශකයා, ඉලක්ක සහ ට්‍රැක්. ඕනෑම තේරීමක් ඕනෑම වේලාවක වෙනස් කිරීමට හෝ ආපසු ගැනීමට හැක.',
  'wb.f_sub_guardian': '{name} සඳහා ඔබ තෝරාගත් දේ, ඔවුන්ගේ උපදේශකයා, ඉලක්ක සහ ට්‍රැක්. ඕනෑම තේරීමක් ඕනෑම වේලාවක වෙනස් කිරීමට හෝ ආපසු ගැනීමට හැක.',
