  'arp.subtitle': 'වෙළඳ නාමය සහිත, නිශ්චිත කාලයක ඇසුරුම්. ඇකඩමියෙන් පිටත කිසිවෙකු දකින්නට පෙර දෙවන පුද්ගලයෙකු සෑම එකක්ම අනුමත කරයි.',
