  'arp.scope.athlete': 'ක්‍රීඩකයා',
  'arp.scope.campus': 'මණ්ඩපය',
  'arp.scope.academy': 'ඇකඩමිය',
  'arp.aud.progress': 'ඇකඩමි හිමිකරුවන්, පරිපාලකයන්, ක්‍රීඩකයාගේ පුහුණුකරු, ක්‍රීඩකයා සහ තහවුරු කළ භාරකරුට කියවිය හැක. මූල්‍ය, වෛද්‍ය හෝ සුබසාධන සටහන්, පුහුණුකරුගේ සහ කාර්ය මණ්ඩලයේ පුද්ගලික අදහස් කිසිවිටෙක ඇතුළත් නොවේ.',
  'arp.aud.term': 'සංවර්ධන වාර්තාවේ කියවන්නන්ම. වාරයේ පැමිණීම සහ බෙදාගෙන ඇත්නම් පාසල් කාණ්ඩය එක් කරයි. පාසල් ලකුණු කිසිවිටෙක මුද්‍රණය නොකෙරේ.',
  'arp.aud.management': 'ඇකඩමි හිමිකරුවන්ට සහ පරිපාලකයන්ට පමණි. 3ට වඩා අඩු කණ්ඩායම් සංඛ්‍යාවක් ලෙස මුද්‍රණය නොකෙරේ. නීතිමය, වෛද්‍ය හෝ පුහුණුකරුගේ පුද්ගලික තොරතුරු නැත.',
  'arp.aud.finance': 'ඇකඩමි හිමිකරුවන්ට, පරිපාලකයන්ට සහ මූල්‍ය අංශයට පමණි. කළමනාකරණ ගිණුම්, නීතිප්‍රකාර හෝ විගණිත ගිණුම් නොවේ. පුහුණු හෝ වෛද්‍ය දත්ත නැත.',
  'arp.aud.campus': 'ඇකඩමි හිමිකරුවන්ට සහ පරිපාලකයන්ට පමණි. එක් මණ්ඩපයක්: පුද්ගලයන්, ක්‍රියාත්මක කිරීම, කාර්ය මණ්ඩලය, මූල්‍ය. 3ට වඩා අඩු කණ්ඩායම් සංඛ්‍යාවක් ලෙස මුද්‍රණය නොකෙරේ.',
  'arp.basis.progress': 'ක්‍රීඩකයාට ආරක්ෂිත ප්‍රගති දසුන: පුහුණුකරුගේ තක්සේරු, ඇකඩමි පැමිණීම සහ අනුමත නිල ප්‍රතිඵල වෙන් වෙන්ව.',
  'arp.basis.term': 'වාරයේ ප්‍රගති දසුන, වාරයේ පැමිණීම සහ බෙදාගෙන ඇත්නම් පාසල් කාණ්ඩය. කිසිවක් එක් ලකුණකට ඒකාබද්ධ නොකෙරේ.',
  'arp.basis.management': 'විධායක මුල් පිටුවේ ඒ අංකවලින්ම කළමනාකරණ දසුන. නීතිප්‍රකාර ගිණුම් නොවේ.',
  'arp.basis.finance': 'මූල්‍ය ලෙජරය, අනුමත වැටුප් සහ තහවුරු කළ ස්ථාන වෙන්කිරීම් වලින් කළමනාකරණ ගිණුම්. නීතිප්‍රකාර හෝ විගණිත නොවේ.',
  'arp.basis.campus': 'විධායක මුල් පිටුවේ සහ ලාභ අලාභයේ ඒ අංකවලින්ම එක් මණ්ඩපයක කළමනාකරණ දසුන.',
