  'acc.mine_empty_title': 'පවරා ඇති විගණන නැත',
  'acc.mine_empty_sub': 'ඇකඩමියක් ඔබව පරීක්ෂක ලෙස නම් කළ විට, විගණනය මෙහි දිස්වේ.',
  'guide.accreditation.title': 'ප්‍රතිපත්තිකරණය සහ විගණන කළමනාකරණය',
  'guide.accreditation.why': 'ඔබේ ඇකඩමිය සතු සෑම බාහිර ප්‍රතිපත්තිකරණයක්, බලපත්‍රයක් සහ තත්ත්ව සලකුණක්ම නිරීක්ෂණය කරන්න, ඒ සඳහා සාක්ෂි ඔබ දැනටමත් පවත්වන වාර්තාවලට සම්බන්ධ කර තබා ගන්න, සහ නිහඬව වෙනස් කළ නොහැකි සොයාගැනීම් සහ නිවැරදි කිරීමේ ක්‍රියාමාර්ග සහිතව විගණන පවත්වන්න.',
  'guide.accreditation.s1': 'ඇකඩමිය විවෘත කර, ප්‍රතිපත්තිකරණය තෝරා, වින්‍යාස කරන්න ඔබා රාමුවක් එක් කරන්න: ප්‍රතිපත්තිකරණ ආයතනය, වර්ගය, මට්ටම, වගකිව යුත්තා, අලුත් කිරීමේ චක්‍රය සහ මතක් කිරීමේ කාලය.',
  'guide.accreditation.s2': 'රාමුව විවෘත කර, සාක්ෂි තෝරා, එයට අවශ්‍ය දේ එක් කර, පසුව පුහුණුකරුගේ සහතික සහ අනුකූලතා වාර්තා සම්බන්ධ කරන්න. කිසිවක් පිටපත් නොවේ, වලංගුභාවය සජීවීව කියවයි.',
  'guide.accreditation.s3': 'විගණනය සැලසුම් කරන්න ඔබා, වර්ගය, දිනය සහ තහවුරු කළ යුතු අංශ තෝරා, අවශ්‍ය නම් පරීක්ෂකවරයෙකු නම් කරන්න; ඔහුට පෙනෙන්නේ එම විගණනය පමණි.',
  'guide.accreditation.s4': 'සෑම සොයාගැනීමක්ම එහි බරපතලකම සහ නිවැරදි කිරීමේ ක්‍රියාමාර්ග සමඟ සටහන් කර, සෑම ක්‍රියාමාර්ගයකටම වගකිව යුත්තෙකු සහ නියමිත දිනයක් දී, වැඩ අවසන් වන විට ඒවා අවසන් ලෙස සලකුණු කරන්න.',
  'guide.accreditation.s5': 'ඉහළ සහ මධ්‍යම සියලු සොයාගැනීම් විසඳූ පසු නැවත ඉදිරිපත් කර, පරීක්ෂකගේ තීරණය සටහන් කරන්න. සෑම පියවරක්ම අගුළු දැමූ අනුපිළිවෙලක තබා ගනී.',
