  'guide.inclusion.why': 'රෝග විනිශ්චයක් හෙළි නොකර, ආබාධිත සහ පැරා ක්‍රීඩකයන්ට ඔබේ වැඩසටහන්වලට සම්බන්ධ වී ඉදිරියට යාමට ඉඩ දෙන්න: වැඩසටහනක් පිරිනමන දේ සකසන්න, සෑම අනුවර්තිත සැසියක්ම සූදානම්දැයි පරීක්ෂා කරන්න, ක්‍රීඩකයන්ට තමන් තෝරන මෙහෙයුම් අවශ්‍යතා පමණක් බෙදාගැනීමට ඉඩ දෙන්න.',
  'guide.inclusion.s1': 'ශාස්ත්‍රාලය, ඉන්පසු ඇතුළත් කිරීම, ඉන්පසු වැඩසටහන් සැකසුම විවෘත කර, වැඩසටහනක් තෝරා, සම්බන්ධ විය හැක්කේ කාටද, ක්‍රීඩා අනුවර්තන ආකෘති, පිරිනමන ගැලපීම්, ස්ථාන පහසුකම් සහ අවශ්‍ය සහාය පුද්ගල අනුපාතය තෝරන්න.',
  'guide.inclusion.s2': 'සැසි ඒවාට සාපේක්ෂව පරීක්ෂා කළ හැකි වන පරිදි, සෑම ස්ථානයකම ප්‍රවේශ පහසුකම් ( සෝපානය, පියගැට රහිත මාර්ගය, ප්‍රවේශ්‍ය ඇඳුම් මාරු කාමරය, තටාක එසවුම) සටහන් කරන ලෙස ස්ථාන කළමනාකරුවන්ගෙන් ඉල්ලන්න.',
  'guide.inclusion.s3': 'ක්‍රීඩකයන්, හෝ තරුණයෙකුගේ සත්‍යාපිත භාරකරු, මගේ ශාස්ත්‍රාලය, ඉන්පසු ගැලපීම් විවෘත කර, කාර්ය මණ්ඩලයට අවශ්‍ය දේ පමණක්, කාටද සහ කවදා දක්වාද යන්න බෙදාගනී. ඔවුන්ට ඕනෑම මොහොතක එය ඉවත් කර ගත හැක.',
  'guide.inclusion.s4': 'ඇතුළත් කිරීම, ඉන්පසු සැසි සූදානම විවෘත කර, සැසියක් තෝරා සියලු හිඩැස් විසඳන්න: ස්ථානය, සහාය පුද්ගලයන්, රාජකාරි ආවරණය සහ ප්‍රධාන පුහුණුකරුගේ සුදුසුකම. පුහුණුකරුවන්ට සහ ස්ථාන කාර්ය මණ්ඩලයට පෙනෙන්නේ ඔවුන් සමඟ බෙදාගත් දේ පමණි, සෑම බැලීමක්ම ක්‍රීඩකයා සඳහා සටහන් වේ.',
  'guide.inclusion.s5': 'තනි ලකුණක් නොව, විස්තරාත්මක මට්ටම් සහිත අනුවර්තිත, පුහුණුකරු මෙහෙයවන ඇගයීම් සටහන් කර, දෙවන ඇගයුම්කරුවෙකු ලවා ඒවා අනුමත කරවන්න. අධ්‍යක්ෂවරුන්ට දළ විශ්ලේෂණයේ පෙනෙන්නේ ගණන් පමණි.',


