  'copar.para_adaptations': 'අනුවර්තනයන්',
  'copar.no_adaptations_yet': 'තවම කිසිදු අනුවර්තනයක් එකතු කර නැත. සහාය අවශ්‍යතා සඳහා විකල්ප උපදෙස් ලබා දෙන්නට එකක් එකතු කරන්න.',
