  'copar.alt_instruction': 'විකල්ප උපදෙස',
  'copar.alt_instruction_ph': 'උදා. පඩිපෙළ වෙනුවට ලෑල්ල භාවිතා කරන්න; හවුල්කරු ස්පර්ශ මාර්ගෝපදේශය ලබා දෙයි',
  'copar.equipment': 'වෙනස් කළ උපකරණ',
  'copar.equipment_ph': 'උදා. රෝද පුටුව, අනුවර්තිත ග්‍රහණය, දෘශ්‍ය ඉලක්කය — එක් පේළියකට එක් අයිතමයක්',
  'copar.cues': 'පුහුණු ලකුණු',
  'copar.cues_ph': 'උදා. තට්ටු සංඥාව සඳහා රැඳී සිටින්න; ඉහළ 明暗 බෝලය ලුහුබඳින්න — එක් පේළියකට එක් ලකුණක්',
