  'copar.accessible_media': 'ප්‍රවේශ සාධ්‍ය මාධ්‍ය',
  'copar.caption_text': 'ශීර්ෂ / ශ්‍රව්‍ය විස්තරය',
  'copar.caption_text_ph': 'වීඩියෝව හෝ රූපය දෙස බැලිය නොහැකි ක්‍රීඩකයින් සඳහා එය දැක්වෙන දෙය විස්තර කරන්න',
  'copar.sr_description': 'තිර-කියවන්නා විස්තරය',
  'copar.sr_description_ph': 'සහාය තාක්ෂණය මගින්声高ට කියවන කෙටි සාමාන්‍ය-පෙළ සංස්කරණය',
